script:
frappe.listview_settings['Bill Payment'] = {
    refresh: function(listview) {
        listview.page.add_inner_button(__('Generate Monthly Bills'), function() {
            frappe.prompt(
                [
                    {
                        label: 'Billing Month',
                        fieldname: 'billing_month',
                        fieldtype: 'Select',
                        options: [
                            'Jan-2026', 'Feb-2026', 'Mar-2026', 'Apr-2026', 
                            'May-2026', 'Jun-2026', 'Jul-2026', 'Aug-2026', 
                            'Sep-2026', 'Oct-2026', 'Nov-2026', 'Dec-2026'
                        ],
                        default: 'Sep-2026',
                        reqd: 1
                    }
                ],
                function(values) {
                    frappe.call({
                        method: 'bill_tracker.api.generate_monthly_bills',
                        args: {
                            billing_month: values.billing_month
                        },
                        freeze: true,
                        freeze_message: __('Generating bills...'),
                        callback: function(r) {
                            if (r.message) {
                                frappe.msgprint(r.message);
                                listview.refresh();
                            }
                        }
                    });
                },
                __('Select Billing Month'),
                __('Generate')
            );
        });
    }
};
